58: const CANON_SMART_LINES = [
59:   'This packet handles the workflow its mode registers.',
60:   'The hub `ROUTER.md` selects it from surface intent.',
61:   'Load only the references this packet declares before acting.',
62:   'Machine-readable signals live in that file, never here.',
63:   'A request that matches no mode falls back to UNKNOWN_FALLBACK.',
64:   'Keep this section prose only: no code block belongs here.',
