69: // Every temp fixture root this run creates, removed when the process exits.
70: const FIXTURE_ROOTS = [];
71: process.on('exit', () => {
72:   for (const root of FIXTURE_ROOTS) fs.rmSync(root, { recursive: true, force: true });
