83: function makeTempHubDir() {
84:   const fixtureRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'parent-skill-check-routing-shape-'));
85:   FIXTURE_ROOTS.push(fixtureRoot);
86:   const hubRoot = path.join(fixtureRoot, HUB_NAME);
