91: // N prose lines, so a fixture can sit at or past the line budget. Each line
92: // stays short so a line-budget fixture never also trips the word cap.
93: function smartLines(count) {
94:   return Array.from(
95:     { length: count },
96:     (_, index) => `Routing line ${index + 1} names the packet and what it loads.`,
97:   );
98: }
