100: // N prose lines of exactly `words` tokens each, so a fixture can sit past the
101: // word cap while staying inside the line budget.
102: function wordySmartLines(count, words) {
103:   const tail = Array.from({ length: words - 1 }, (_, index) => `token${index + 1}`);
104:   return Array.from({ length: count }, (_, index) => [`line${index + 1}`, ...tail].join(' '));
105: }
