107: // A hub SKILL.md in the routing canon: short SMART ROUTING prose and one link
108: // to the root router. The router itself lives in the sibling file.
109: function canonHubSkillMd() {
110:   return [
111:     '---',
112:     `name: ${HUB_NAME}`,
113:     'version: 1.0.0.0',
114:     'allowed-tools: [Read]',
115:     '---',
116:     `# ${HUB_NAME}`,
117:     '',
118:     '## 2. SMART ROUTING',
119:     '',
120:     'The advisor routes a prompt to this hub identity, and the hub reads',
121:     '`mode-registry.json` to pick the mode. Stage two lives in root',
122:     '[`ROUTER.md`](./ROUTER.md).',
123:     '',
124:   ].join('\n');
125: }
