127: // One `## MACHINE ROUTER` section as a fixture writes it: the heading, then the
128: // machine block unless `block` is null, so a prose-only section is one argument.
129: function routerSection({ heading = '## MACHINE ROUTER', block = CANON_ROUTER_BLOCK } = {}) {
130:   return { heading, block };
131: }
