133: // A packet SKILL.md in the routing canon: short prose, the pointer, and no
134: // router section. The knobs build each defect.
135: function packetSkillMd(name, {
136:   smart = CANON_SMART_LINES,
137:   pointer = true,
138:   pointerTarget = './ROUTER.md',
139:   pointerLines = null,
140:   pointerOnHeading = false,
141:   frontmatterLink = false,
142:   routerSections = [],
143:   trailingH2 = false,
144: } = {}) {
145:   const frontmatter = ['---', `name: ${name}`];
146:   // Frontmatter metadata loads with the skill, so a link there points at the
147:   // router without ever being the body's pointer.
148:   if (frontmatterLink) frontmatter.push('see: "Routing detail: [`ROUTER.md`](./ROUTER.md)"');
149:   frontmatter.push('---');
150:   const heading = pointerOnHeading
151:     ? `## 2. SMART ROUTING [\`ROUTER.md\`](${pointerTarget})`
152:     : '## 2. SMART ROUTING';
153:   const lines = [...frontmatter, `# ${name}`, '', heading, '', ...smart, ''];
154:   if (pointer) lines.push(...(pointerLines || [pointerLine(pointerTarget)]), '');
155:   for (const section of routerSections) {
156:     lines.push(section.heading, '');
157:     if (section.block !== null) lines.push('```python', ...section.block, '```', '');
158:   }
159:   if (trailingH2) lines.push('## 3. HOW IT WORKS', '', 'The packet body follows the router.', '');
160:   return lines.join('\n');
161: }
