324: // The ledger path is always overridden to a file that does not exist, and an
325: // inherited skills root is cleared, so no case can pass or fail because of the
326: // live ledger or a stray environment variable.
327: function runChecker(hubRoot, envOverrides = {}) {
328:   const env = { ...process.env };
329:   delete env.PARENT_HUB_CHECK_STRICT;
330:   delete env.ROUTING_SHAPE_SKILLS_ROOT;
331:   env.ROUTING_SHAPE_DEBT_FILE = path.join(path.dirname(hubRoot), 'absent-routing-shape-debt.json');
332:   const result = spawnSync(process.execPath, [CHECKER_PATH, hubRoot], {
333:     encoding: 'utf8',
334:     env: { ...env, ...envOverrides },
335:   });
336:   return { status: result.status, stdout: `${result.stdout || ''}${result.stderr || ''}` };
337: }
