339: // The checker's closing summary is also a FAIL line, so it is not a finding.
340: function failLines(stdout) {
341:   return stdout.split('\n')
342:     .filter((line) => line.startsWith('FAIL: ') && !line.startsWith('FAIL: parent-skill-check '));
